import { requireAdminSession } from "../../../../../../lib/admin-session";import { adminVendorsWorkspace, transitionVendorApplication } from "../../../../../../lib/admin-runtime";import type { VendorOnboardingState } from "@buy-local-sparta/core";
const allowed=new Set<VendorOnboardingState>(["verification_pending","catalog_onboarding","test_ready","active","restricted","suspended","closed"]);
export async function POST(request:Request,context:{params:Promise<{id:string}>}){try{const p=await requireAdminSession(request,{csrf:true,permission:"vendor.manage"});const {id}=await context.params;const b=await request.json() as {to?:unknown;reason?:unknown};if(typeof b.to!=="string"||!allowed.has(b.to as VendorOnboardingState))throw new Error("Invalid vendor transition");if(typeof b.reason!=="string"||b.reason.trim().length<3)throw new Error("Transition reason is required");await transitionVendorApplication(p,{applicationId:id,to:b.to as VendorOnboardingState,reason:b.reason});return Response.json(await adminVendorsWorkspace(p))}catch(e){return Response.json({error:e instanceof Error?e.message:"vendor_transition_failed"},{status:400})}}
